{
  "number": 1,
  "date": "2026-09-16",
  "slug": "alignment-jumpers-knee",
  "topic": "Jumper's Knee",
  "tags": ["patellar tendinopathy", "jumper's knee", "volleyball", "alignment", "screening"],

  "paper": {
    "title": "Comparison of lower limb alignment in knees with and without patellar tendinopathy among elite volleyball players: a cross-sectional study",
    "authors": "Saraee et al.",
    "journal": "J Orthop Surg Res",
    "year": 2026,
    "doi": "10.1186/s13018-026-07229-w",
    "url": "https://link.springer.com/article/10.1186/s13018-026-07229-w",
    "source": "doi",
    "zotero_key": "",
    "full_text": false
  },

  "hook": "Bow legs, knock knees, angled shins: does the way the leg bones line up explain jumper's knee in elite volleyball players?",

  "trust": {
    "level": "Preliminary",
    "design": "Cross-sectional, one visit",
    "sample": "22 elite male volleyball players",
    "limitations": [
      "Small group of men from one region",
      "Compared legs within players, not injured vs healthy players",
      "Standing X-rays only; no landing or jump load data"
    ]
  },

  "did": {
    "question": "In players with jumper's knee, does leg alignment on the painful side differ from the pain-free side?",
    "facts": [
      { "label": "Design", "value": "Cross-sectional, one visit" },
      { "label": "Who", "value": "22 elite male volleyball players" },
      { "label": "Measured", "value": "7 alignment angles on X-rays" }
    ],
    "bullets": [
      "Checked players for jumper's knee with a standard clinical pain test.",
      "Took standing X-rays of the legs.",
      "Measured 7 angles that describe how the thigh and shin bones line up, viewed from the front.",
      "Compared knees with tendon pain against knees without it."
    ]
  },

  "results": {
    "stats": [
      { "value": "22", "label": "elite male volleyball players studied", "page": "Abstract" },
      { "value": "7", "label": "thigh and shin alignment angles measured", "page": "Abstract" },
      { "value": "0 of 7", "label": "angles differed between painful and pain-free knees", "page": "Abstract" }
    ],
    "bullets": [
      "No alignment angle at the thigh, knee, or shin separated knees with and without jumper's knee.",
      "The authors conclude jumper's knee in these players is unlikely to be linked to static leg alignment.",
      "They point to training load and movement patterns instead. This study did not measure those."
    ]
  },

  "meaning": {
    "summary": "How the leg bones line up at rest did not explain jumper's knee here. How athletes load and move is the more likely place to look.",
    "roles": [
      { "role": "Sports Medicine", "line": "Standing alignment did not explain the painful knee. Start with jump load history and landing mechanics." },
      { "role": "Strength and Conditioning", "line": "Bone angles are fixed; jump volume and landing quality are trainable. Spend effort where we can act." },
      { "role": "Sport Science", "line": "In jumping sports, jump counts and landing asymmetries may tell us more than a static screen." },
      { "role": "Sport Coaches", "line": "Leg shape alone is not a red flag. Watch jump volume in high-rep practice weeks." }
    ]
  },

  "takeaways": {
    "bullets": [
      "Watch jump load and landing mechanics before blaming leg alignment for knee tendon pain.",
      "Pilot simple jump counts in volleyball practice and compare them with knee pain reports.",
      "Treat one static screen as context, not a verdict on an athlete's tendon risk."
    ],
    "question": "When an athlete's knee tendon pain flares, what do we check first, and is it something we can change?"
  }
}

